def wolfePhaseDefect (P : JLMS.AtomicDualModel 𝕜 Y)
    (μ : WeakDual 𝕜 (JLMS.CZero 𝕜 Y)) (f : JLMS.CZero 𝕜 Y) (D : Set Y) : ℝ :=
  wolfeMass P μ D - RCLike.re (JLMS.atomicRestriction P D (WeakDual.toStrongDual μ) f)

